describe("doctests of sympy.polys.modulargcd", () => {
  it("h == x + sqrt(2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, pow(2, rational(1, 2))), [])).equals(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, pow(2, rational(1, 2))), []))))).toBe('True');
  });
  it("cff * h == f", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(-2, pow(x, 2)), [])).equals(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(-2, pow(x, 2)), []))))).toBe('True');
  });
  it("cfg * h == g", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, pow(2, rational(1, 2))), [])).equals(new PolyRing([x], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, pow(2, rational(1, 2))), []))))).toBe('True');
  });
  it("h == x + sqrt(2)*y", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), []))))).toBe('True');
  });
  it("cff * h == f (2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(pow(x, 2), mul(2, pow(y, 2)), mul(2, x, y, pow(2, rational(1, 2)))), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(pow(x, 2), mul(2, pow(y, 2)), mul(2, x, y, pow(2, rational(1, 2)))), []))))).toBe('True');
  });
  it("cfg * h == g (2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), []))))).toBe('True');
  });
  it("h == R.one", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(rational(1), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(rational(1), []))))).toBe('True');
  });
  it("cff * h == f (3)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, mul(y, pow(2, rational(1, 2)))), []))))).toBe('True');
  });
  it("cfg * h == g (3)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, y), [])).equals(new PolyRing([x, y], QQ.algebraicField(pow(2, rational(1, 2))), 'lex').fromExpr(xreplace(add(x, y), []))))).toBe('True');
  });
  it("h, cff, cfg", () => {
    const [x, y] = symbols('x y');
    const v1 = modgcdBivariate(new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(pow(x, 2), mul(-1, pow(y, 2))), [])), new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(pow(x, 2), pow(y, 2), mul(2, x, y)), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(x + y, x - y, x + y)')).toBe(true);
  });
  it("h, cff, cfg (2)", () => {
    const [x, y] = symbols('x y');
    const v1 = modgcdBivariate(new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(4, mul(-1, pow(x, 2)), mul(-4, y), mul(y, pow(x, 2))), [])), new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(2, x), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(x + 2, x*y - x - 2*y + 2, 1)')).toBe(true);
  });
  it("h, cff, cfg (3)", () => {
    const [x, y] = symbols('x y');
    const v1 = modgcdMultivariate(new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(pow(x, 2), mul(-1, pow(y, 2))), [])), new PolyRing([x, y], ZZ, 'lex').fromExpr(xreplace(add(pow(x, 2), pow(y, 2), mul(2, x, y)), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(x + y, x - y, x + y)')).toBe(true);
  });
  it("h, cff, cfg (4)", () => {
    const [x, y, z] = symbols('x y z');
    const v1 = modgcdMultivariate(new PolyRing([x, y, z], ZZ, 'lex').fromExpr(xreplace(add(mul(x, pow(z, 2)), mul(-1, y, pow(z, 2))), [])), new PolyRing([x, y, z], ZZ, 'lex').fromExpr(xreplace(add(z, mul(z, pow(x, 2))), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(z, x*z - y*z, x**2 + 1)')).toBe(true);
  });
  it("h, cff, cfg (5)", () => {
    const x = new Sym('x');
    const v1 = modgcdUnivariate(new PolyRing([x], ZZ, 'lex').fromExpr(xreplace(add(-1, pow(x, 5)), [])), new PolyRing([x], ZZ, 'lex').fromExpr(xreplace(add(-1, x), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(x - 1, x**4 + x**3 + x**2 + x + 1, 1)')).toBe(true);
  });
  it("h, cff, cfg (6)", () => {
    const x = new Sym('x');
    const v1 = modgcdUnivariate(new PolyRing([x], ZZ, 'lex').fromExpr(xreplace(add(-6, mul(6, pow(x, 2))), [])), new PolyRing([x], ZZ, 'lex').fromExpr(xreplace(add(2, mul(2, pow(x, 2)), mul(4, x)), [])));
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(2*x + 2, 3*x - 3, x + 1)')).toBe(true);
  });
});

